import type { SignatureData, StyleOpts } from '../types'
import { renderSignature } from './render'
import { SOCIALS, parseSocialValue } from './icons'
import { normalizeData, normalizeUrl } from './validation'

export function wrapDocument(inner: string): string {
  return `<!DOCTYPE html>
<html>
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>Email signature</title>
</head>
<body style="margin:0;padding:24px;background:#ffffff;">
<!-- Generated by SigFree -->
${inner}
</body>
</html>
`
}

/**
 * Copy rendered markup as rich content so pasting into Gmail/Outlook
 * inserts the formatted signature instead of raw code.
 */
export async function copyRich(html: string): Promise<{ ok: boolean; rich: boolean }> {
  const parsed = new DOMParser().parseFromString(html, 'text/html')
  parsed.querySelectorAll('style,script').forEach((element) => element.remove())
  parsed.querySelectorAll('br,td,div,p,tr').forEach((element) => element.append('\n'))
  const text = (parsed.body.textContent ?? '').replace(/\s+/g, ' ').trim()
  try {
    if (typeof ClipboardItem !== 'undefined' && navigator.clipboard?.write) {
      const item = new ClipboardItem({
        'text/html': new Blob([html], { type: 'text/html' }),
        'text/plain': new Blob([text], { type: 'text/plain' }),
      })
      await navigator.clipboard.write([item])
      return { ok: true, rich: true }
    }
  } catch {
    // Older browsers can still copy rich text through the copy event.
  }
  const area = document.createElement('textarea')
  area.value = text
  area.style.cssText = 'position:fixed;opacity:0;'
  const active = document.activeElement
  let rich = false
  const onCopy = (event: ClipboardEvent): void => {
    if (!event.clipboardData) return
    event.clipboardData.setData('text/html', html)
    event.clipboardData.setData('text/plain', text)
    event.preventDefault()
    rich = true
  }
  try {
    document.body.appendChild(area)
    area.select()
    document.addEventListener('copy', onCopy)
    if (document.execCommand('copy') && rich) return { ok: true, rich: true }
  } catch {
    // Return readable text if the browser denies both rich clipboard methods.
  } finally {
    document.removeEventListener('copy', onCopy)
    area.remove()
    if (active instanceof HTMLElement) active.focus()
  }
  const ok = await copyText(text)
  return { ok, rich: false }
}

/** iCloud.com uses a text signature. Keep contact details and links readable. */
export function exportPlainText(raw: SignatureData): string {
  const data = normalizeData(raw)
  const socials = SOCIALS.flatMap((network) => {
    const parsed = parseSocialValue(network, data.socials[network.key] ?? '')
    const url = parsed && normalizeUrl(parsed.profileUrl, true)
    return url ? [`${network.label}: ${url}`] : []
  })
  const cta = normalizeUrl(data.cta.url)
  return [
    data.name,
    [data.title, data.company].map((value) => value.trim()).filter(Boolean).join(' · '),
    data.phone,
    data.mobile ? `Mobile: ${data.mobile}` : '',
    data.email,
    data.website,
    data.address,
    ...socials,
    data.cta.text && cta ? `${data.cta.text}: ${cta}` : '',
    data.disclaimer,
  ].map((value) => value.trim()).filter(Boolean).join('\n')
}

export async function copyText(text: string): Promise<boolean> {
  try {
    await navigator.clipboard.writeText(text)
    return true
  } catch {
    const area = document.createElement('textarea')
    try {
      area.value = text
      area.style.position = 'fixed'
      area.style.opacity = '0'
      document.body.appendChild(area)
      area.select()
      return document.execCommand('copy')
    } catch {
      return false
    } finally {
      area.remove()
    }
  }
}

export function downloadFile(filename: string, content: string, mime = 'text/html;charset=utf-8'): void {
  const blob = new Blob([content], { type: mime })
  const url = URL.createObjectURL(blob)
  const anchor = document.createElement('a')
  anchor.href = url
  anchor.download = filename
  document.body.appendChild(anchor)
  anchor.click()
  document.body.removeChild(anchor)
  URL.revokeObjectURL(url)
}

export function exportHtml(data: SignatureData, style: StyleOpts): string {
  return wrapDocument(renderSignature(data, style))
}

export function exportJson(data: SignatureData, style: StyleOpts, freeform?: { html: string; enabled: boolean }): string {
  return JSON.stringify({ version: 1, data, style, freeform }, null, 2)
}
